672	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
673	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
674	/// (including "+1", " 1", "1.0", "", "-1", or an argument that is not valid
675	/// UTF-8) is rejected as a usage error.
676	fn parse_index(arg: &OsStr) -> Option<u64> {
677	    let text = arg.to_str()?;
678	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
679	        return None;
680	    }
681	    let mut value: u64 = 0;
682	    for b in text.bytes() {
683	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
684	    }
685	    Some(value)
686	}
