688	/// Build the one-line JSON object printed by `prove`: integer tree_size and
689	/// leaf_index, the lowercase-hex root, and the audit path as a JSON array of
690	/// lowercase-hex hashes ordered leaf to root.
691	fn proof_json(tree_size: u64, leaf_index: u64, root: &[u8; 32], audit_path: &[[u8; 32]]) -> String {
692	    let mut out = String::new();
693	    out.push_str("{\"tree_size\":");
694	    out.push_str(&tree_size.to_string());
695	    out.push_str(",\"leaf_index\":");
696	    out.push_str(&leaf_index.to_string());
697	    out.push_str(",\"root\":\"");
698	    out.push_str(&hex(root));
699	    out.push_str("\",\"audit_path\":[");
700	    for (i, node) in audit_path.iter().enumerate() {
701	        if i > 0 {
702	            out.push(',');
703	        }
704	        out.push('"');
705	        out.push_str(&hex(node));
706	        out.push('"');
707	    }
708	    out.push_str("]}");
709	    out
710	}
