734	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
735	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
736	    let mut input = Vec::with_capacity(65);
737	    input.push(0x01);
738	    input.extend_from_slice(left);
739	    input.extend_from_slice(right);
740	    sha256(&input)
741	}
