743	/// Construct the RFC 6962 Merkle tree over a batch. This is the SINGLE place
744	/// that maintains the tree-construction rules: both `root` (via `mth`) and
745	/// `prove` (via `root_and_path`) build their leaves and subtrees here, so the
746	/// two commands can never disagree on how a batch is shaped or hashed.
747	///
748	/// ```text
749	/// MTH([])      = SHA-256("")
750	/// MTH([d])     = SHA-256(0x00 || d)
751	/// MTH(d0..dn)  = SHA-256(0x01 || MTH(d0..dk) || MTH(dk..dn))
752	/// ```
753	///
754	/// with k the largest power of two strictly smaller than n. Uneven batches
755	/// are handled by the recursion itself: no leaf is duplicated and no empty
756	/// record is appended to round the size up to a power of two.
757	///
758	/// `target` selects the one leaf a membership proof is built for:
759	///
760	/// ```text
761	/// PATH(m, [d0]) = []
762	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
763	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
764	/// ```
765	///
766	/// When `target` is `Some(m)`, the sibling subtree hashes on the route from
767	/// leaf `m` to the root are appended to `path` in leaf-to-root order
768	/// (RFC 6962 section 2.1.1); the reindexed `Some(m - k)` follows the audited
769	/// leaf into whichever subtree contains it, while the sibling subtree is
770	/// built with `None`. With `None` only the root is built. Every leaf hash and
771	/// every interior hash is computed exactly once in either mode, so producing
772	/// a proof costs the same 2n - 1 SHA-256 invocations as the root alone.
773	fn build_tree(
774	    leaves: &[&[u8]],
775	    target: Option<usize>,
776	    path: &mut Vec<[u8; 32]>,
777	) -> [u8; 32] {
778	    match leaves.len() {
779	        0 => sha256(&[]),
780	        1 => leaf_hash(leaves[0]),
781	        n => {
782	            // Largest power of two strictly smaller than n.
783	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
784	            let (left_leaves, right_leaves) = leaves.split_at(k);
785	            match target {
786	                // The audited leaf is in the left subtree; the right subtree
787	                // hash is this level's sibling on the leaf-to-root path.
788	                Some(m) if m < k => {
789	                    let left = build_tree(left_leaves, Some(m), path);
790	                    let right = build_tree(right_leaves, None, path);
791	                    path.push(right);
792	                    node_hash(&left, &right)
793	                }
794	                // The audited leaf is in the right subtree; reindex it
795	                // relative to that subtree and take the left subtree as the
796	                // sibling.
797	                Some(m) => {
798	                    let left = build_tree(left_leaves, None, path);
799	                    let right = build_tree(right_leaves, Some(m - k), path);
800	                    path.push(left);
801	                    node_hash(&left, &right)
802	                }
803	                // No audited leaf: both subtrees are plain root constructions.
804	                None => {
805	                    let left = build_tree(left_leaves, None, path);
806	                    let right = build_tree(right_leaves, None, path);
807	                    node_hash(&left, &right)
808	                }
809	            }
810	        }
811	    }
812	}
