814	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256: the batch root, built
815	/// by the shared `build_tree` constructor so it follows exactly the same
816	/// rules as proof generation.
817	fn mth(leaves: &[&[u8]]) -> [u8; 32] {
818	    build_tree(leaves, None, &mut Vec::new())
819	}
