871	    let bit_len = (data.len() as u64).wrapping_mul(8);
872	    let mut msg = data.to_vec();
873	    msg.push(0x80);
874	    while msg.len() % 64 != 56 {
875	        msg.push(0);
876	    }
877	    msg.extend_from_slice(&bit_len.to_be_bytes());
