879	    for block in msg.chunks_exact(64) {
880	        let mut w = [0u32; 64];
881	        for (i, word) in block.chunks_exact(4).enumerate() {
882	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
883	        }
884	        for i in 16..64 {
885	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
886	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
