1039	            let root = mth(&refs);
1040	            for m in 0..n {
1041	                let (fused_root, path) = root_and_path(&refs, m);
1042	                assert_eq!(
1043	                    hex_of(&fused_root),
1044	                    hex_of(&root),
1045	                    "single-pass root must equal mth at n={n}, m={m}"
1046	                );
1047	                if n == 1 {
1048	                    assert!(path.is_empty(), "single record must have an empty path");
1049	                } else {
1050	                    // Path length is bounded by the tree depth; for an even
1051	                    // power-of-two batch every position sits at full depth.
1052	                    let depth = usize::BITS - (n - 1).leading_zeros();
1053	                    if n.is_power_of_two() {
1054	                        assert_eq!(path.len(), depth as usize, "n={n}, m={m}");
1055	                    } else {
1056	                        assert!(path.len() <= depth as usize, "n={n}, m={m}");
1057	                    }
1058	                }
1059	                let computed = rfc_recompute_root(refs[m], m, n, &path);
1060	                assert_eq!(hex_of(&computed), hex_of(&root), "proof mismatch at n={n}, m={m}");
1061	            }
