1066	    fn proof_generation_hashes_every_leaf_and_subtree_exactly_once() {
1067	        // A batch of n records has n leaf hashes and n - 1 interior node
1068	        // hashes. Computing the root and one audit path in a single pass must
1069	        // cost exactly 2n - 1 SHA-256 invocations: the old two-phase
1070	        // implementation (mth for the root, then inclusion_path recomputing
