1239	    fn parse_proof_rejects_missing_fields_and_empty_or_wrong_container() {
1240	        let refs: Vec<&[u8]> = vec![b"a", b"b"];
1241	        let (root, path) = root_and_path(&refs, 0);
1242	        let full = valid_proof_bytes(2, 0, &root, &path);
1243	        assert!(parse_proof(&full).is_ok());
1244	
1245	        let drop_field = |bytes: &[u8], needle: &str| -> Vec<u8> {
1246	            let text = String::from_utf8(bytes.to_vec()).unwrap();
1247	            // Rebuild without the named member by string surgery on the
1248	            // canonical compact form emitted by proof_json.
1249	            let idx = text.find(needle).unwrap();
1250	            let mut end = idx + needle.len();
1251	            // Consume through the member's value terminator.
1252	            match needle {
1253	                "\"tree_size\":" | "\"leaf_index\":" => {
1254	                    while end < text.len()
1255	                        && text.as_bytes()[end] != b','
1256	                        && text.as_bytes()[end] != b'}'
1257	                    {
1258	                        end += 1;
1259	                    }
1260	                }
1261	                "\"root\":" => {
1262	                    while end < text.len() && text.as_bytes()[end] != b'"' {
1263	                        end += 1;
1264	                    }
1265	                    end += 1;
1266	                }
1267	                _ => {
1268	                    end = text.rfind(']').unwrap() + 1;
1269	                }
1270	            }
1271	            let mut s = String::new();
1272	            s.push_str(&text[..idx]);
1273	            let rest = &text[end..];
1274	            // Tidy the separator left by the removed member.
1275	            if rest.starts_with(',') {
1276	                s.push_str(&rest[1..]);
1277	            } else if text[..idx].ends_with(',') {
1278	                s.pop();
1279	                s.push_str(rest);
1280	            } else {
1281	                s.push_str(rest);
1282	            }
1283	            s.into_bytes()
1284	        };
1285	
1286	        for key in ["\"tree_size\":", "\"leaf_index\":", "\"root\":", "\"audit_path\":"] {
1287	            let cut = drop_field(&full, key);
1288	            assert!(parse_proof(&cut).is_err(), "proof missing {key} must be invalid: {cut:?}");
1289	        }
1290	
1291	        for bad in [
1292	            b"".as_slice(),
1293	            b"   ",
1294	            b"null",
1295	            b"[]",
1296	            b"\"x\"",
1297	            b"123",
