1418	    fn verify_accepts_real_proofs_at_every_position_of_many_sizes() {
1419	        let sizes: Vec<usize> = (1..=18).chain([31, 32, 33, 63, 64, 65, 100, 127, 128, 257]).collect();
1420	        for n in sizes {
1421	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
1422	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
1423	            let root = mth(&refs);
1424	            for m in 0..n {
1425	                verify_record(&refs, m, refs[m], n as u64).unwrap_or_else(|e| {
1426	                    panic!("n={n} m={m} must verify: {e}")
1427	                });
1428	                // The proof must not be trusted by itself: a different
1429	                // trusted size or root always fails.
1430	                assert!(verify_record(&refs, m, refs[m], n as u64 + 1).is_err());
1431	                let mut other_root = root;
1432	                other_root[0] ^= 0x01;
1433	                let (_, path) = root_and_path(&refs, m);
1434	                let bytes = proof_json(n as u64, m as u64, &root, &path).into_bytes();
1435	                let proof = parse_proof(&bytes).unwrap();
1436	                assert!(verify_proof(&proof, refs[m], n as u64, &other_root).is_err());
1437	            }
1438	        }
1439	    }
