        let good = format!("{{\"tree_size\":2,\"leaf_index\":0,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}");
        assert!(parse_proof(good.as_bytes()).is_ok());

        let cases = [
            format!("{{\"tree_size\":\"2\",\"leaf_index\":0,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}"),
